SourceCode.Declaration:
/// <summary>
/// Stock count control center: Check for duplicates - re-checks the selected stock count.
/// </summary>
class HSMobileOpsCountRefresh
{
}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsCountMaster master = _args ? _args.record() : null;

    if (!master || !master.RecId)
    {
        throw error('Select a stock count first.');
    }
    HSMobileOpsCountControl::refresh(master.RecId);
    if (_args && _args.caller() is FormRun)
    {
        FormRun callerForm = _args.caller() as FormRun;
        int     i;
        for (i = 1; i <= callerForm.dataSourceCount(); i++)
        {
            callerForm.dataSource(i).research(true);
        }
    }
}
